function goToSettings(){location.hash=`#/parametres`}function renderSettingsThemeChoice(){const choice=getThemeChoice();document.querySelectorAll(`#settingsPage [data-theme-choice]`).forEach(btn=>{btn.setAttribute(`aria-checked`,String(btn.dataset.themeChoice===choice))})}function renderSettingsVolumeRow(){document.getElementById(`settingsVolumeRow`).hidden=!getSoundEnabled()}function settingsServiceLabel(key){return String(key).replace(/(^|[\s-])(\S)/g,(m,sep,c)=>sep+c.toUpperCase())}function renderSettingsSubs(){const mine=Array.from(getMyStreamingServices()).sort((a,b)=>a.localeCompare(b,`fr`));document.getElementById(`settingsSubsSub`).textContent=mine.length?mine.map(settingsServiceLabel).join(`, `):`Aucun : toutes les plateformes s’affichent sur tes affiches`}const SETTINGS_REGION_SUGGESTED=[`FR`,`BE`,`CH`,`CA`,`LU`,`ZA`,`GB`,`US`];const SETTINGS_REGION_MAX=8;const regionSearchKey=s=>String(s).normalize(`NFD`).replace(/[̀-ͯ]/g,``).toLowerCase();function settingsRegionMatches(query){const q=regionSearchKey(query.trim());const current=getWatchRegion();if(!q){return[current,...SETTINGS_REGION_SUGGESTED.filter(c=>c!==current)].slice(0,SETTINGS_REGION_MAX)}return WATCH_REGIONS.map(code=>({code,key:regionSearchKey(watchRegionName(code))})).filter(r=>r.key.includes(q)||r.code.toLowerCase()===q).sort((a,b)=>b.key.startsWith(q)-a.key.startsWith(q)||a.key.localeCompare(b.key,`fr`)).slice(0,SETTINGS_REGION_MAX).map(r=>r.code)}function renderSettingsRegionList(){const list=document.getElementById(`settingsRegionList`);const codes=settingsRegionMatches(document.getElementById(`settingsRegionSearch`).value);const current=getWatchRegion();list.innerHTML=codes.length?codes.map(code=>`<button type="button" class="st-region-opt" role="option" data-region="${code}" aria-selected="${code===current}">${escapeHtml(watchRegionName(code))}</button>`).join(``):`<p class="st-region-empty">Aucun pays de ce nom.</p>`}function renderSettingsRegion(){document.getElementById(`settingsRegionVal`).textContent=watchRegionName(getWatchRegion())}function toggleSettingsRegionPanel(open){const panel=document.getElementById(`settingsRegionPanel`);const btn=document.getElementById(`settingsRegionBtn`);const show=typeof open===`boolean`?open:panel.hidden;panel.hidden=!show;btn.setAttribute(`aria-expanded`,String(show));if(show){const search=document.getElementById(`settingsRegionSearch`);search.value=``;renderSettingsRegionList();search.focus()}}function chooseSettingsRegion(code){setWatchRegion(code);renderSettingsRegion();toggleSettingsRegionPanel(false);document.getElementById(`settingsRegionBtn`).focus();showToast(`Plateformes : ${watchRegionName(getWatchRegion())}`)}function renderSettingsPublic(){const on=!!(currentProfile&&currentProfile.public_profile);document.getElementById(`settingsPublicToggle`).checked=on;document.getElementById(`settingsPublicSub`).textContent=on?`Visible avec ton lien, sans tes films privés ni tes commentaires`:`Personne ne peut le voir`}function openSettingsPage(){renderSettingsThemeChoice();document.getElementById(`reduceMotionToggle`).checked=getReduceMotion();document.getElementById(`soundToggle`).checked=getSoundEnabled();renderSettingsVolumeRow();renderSettingsSubs();renderSettingsOffline();renderSettingsRegion();toggleSettingsRegionPanel(false);renderSettingsPublic();updateInstallUI()}function openSettingsModal(){goToSettings()}function closeSettingsModal(){closeOverlay(`settingsOverlay`)}document.getElementById(`openSettingsBtn`).addEventListener(`click`,()=>{closeProfileModal();goToSettings()});document.getElementById(`closeSettings`).addEventListener(`click`,closeSettingsModal);document.getElementById(`settingsPageBack`).addEventListener(`click`,()=>returnToProfile());document.querySelectorAll(`#settingsPage [data-theme-choice]`).forEach(btn=>{btn.addEventListener(`click`,()=>{setTheme(btn.dataset.themeChoice);renderSettingsThemeChoice()})});document.getElementById(`soundToggle`).addEventListener(`change`,renderSettingsVolumeRow);document.getElementById(`settingsSubsBtn`).addEventListener(`click`,()=>{goToWatchlist();if(typeof openMyServicesPanelWhenReady===`function`)openMyServicesPanelWhenReady()});document.getElementById(`settingsRegionBtn`).addEventListener(`click`,()=>toggleSettingsRegionPanel());document.getElementById(`settingsRegionSearch`).addEventListener(`input`,renderSettingsRegionList);document.getElementById(`settingsRegionSearch`).addEventListener(`keydown`,e=>{if(e.key===`Enter`){e.preventDefault();const first=settingsRegionMatches(e.target.value)[0];if(first)chooseSettingsRegion(first)}else if(e.key===`Escape`){e.preventDefault();toggleSettingsRegionPanel(false);document.getElementById(`settingsRegionBtn`).focus()}});document.getElementById(`settingsRegionList`).addEventListener(`click`,e=>{const opt=e.target.closest(`[data-region]`);if(opt)chooseSettingsRegion(opt.dataset.region)});document.getElementById(`settingsPublicToggle`).addEventListener(`change`,async e=>{const on=e.target.checked;const ok=await savePublicProfile(on);if(!ok)e.target.checked=!on;renderSettingsPublic()});document.getElementById(`settingsPage`).addEventListener(`click`,e=>{const row=e.target.closest(`[data-proxy]`);if(!row)return;const target=document.getElementById(row.dataset.proxy);if(target)target.click()});